    "new_messages = [\n",
    "    \"Please submit your machine learning assignment by tomorrow.\",\n",
    "    \"Congratulations! Claim your free gift now.\",\n",
    "    \"The placement aptitude test starts at 9 AM on Saturday.\",\n",
